"""Install the latest checked web-only build, preserving the API and server settings.

Uses the same validated public GitHub update channel and rollback as Settings > Update.
Prepare by default; --apply activates the static browser/PWA assets only.
"""
import base64
import gzip
import json
import os
import runpy
import sys
import tempfile
from pathlib import Path

PAYLOAD = ''  # noqa: E501 - reviewed public updater modules


def bundle():
    return json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))


def main():
    root = Path(tempfile.mkdtemp(prefix="dhanz-preview-setup-", dir=Path.home()))
    root.chmod(0o700)
    for name, source in bundle().items():
        target = root / name
        target.write_text(source)
        target.chmod(0o600)
    sys.path.insert(0, str(root))
    runpy.run_path(str(root / "apply_web_release.py"), run_name="__main__")


if __name__ == "__main__":
    os.umask(0o077)
    main()
